+wmem_strbuf_t *ws_unescape_string_len(wmem_allocator_t *alloc, const char *string, ssize_t len)
+{
+    wmem_strbuf_t *buf;
+    size_t abs_len, i;
+    char c;
+
+    abs_len = (len < 0) ? strlen(string) : (size_t)len;
+
+    buf = wmem_strbuf_new_sized(alloc, abs_len);
+
+    /* This is permissive and passes through unrecognized escapes and
+     * incomplete escapes at the end. We could have a strict mode, though
+     * a proper strict mode would have to distinguish between strict-for-C,
+     * strict-for-C++, strict-for-JSON, strict-for-Python, etc. */
+    for (i = 0; i < abs_len; i++) {
+        c = string[i];
+        if (c == '\\' && i + 1 < abs_len) {
+            c = string[++i];
+            switch (c) {
+            case 'a':
+                wmem_strbuf_append_c(buf, '\a');
+                break;
+            case 'b':
+                wmem_strbuf_append_c(buf, '\b');
+                break;
+            case 'f':
+                wmem_strbuf_append_c(buf, '\f');
+                break;
+            case 'n':
+                wmem_strbuf_append_c(buf, '\n');
+                break;
+            case 'r':
+                wmem_strbuf_append_c(buf, '\r');
+                break;
+            case 't':
+                wmem_strbuf_append_c(buf, '\t');
+                break;
+            case 'v':
+                wmem_strbuf_append_c(buf, '\v');
+                break;
+            case '\\':
+                wmem_strbuf_append_c(buf, '\\');
+                break;
+            case '\"':
+                wmem_strbuf_append_c(buf, '\"');
+                break;
+            case '\'':
+                wmem_strbuf_append_c(buf, '\'');
+                break;
+            // XXX - C has \? for supporting the unlamented trigraphs
+            // Backslash followed by a literal newline for line continuation?
+#if 0
+            case 'x':
+            {
+                // Our output is UTF-8, limit to 2 characters max
+                int bin;
+                char out;
+                if (i + 1 < abs_len) {
+                    c = string[++i];
+                    bin = ws_xton(c);
+                    if (bin == -1) {
+                        // fail
+                    }
+                    if (i + 1 < abs_len) {
+                        c = string[++i];
+                        bin = ws_xton(c);
+                        if (bin == -1) {
+
+                        }
+                    }
+                }
+                for (unsigned j = 0; i + j < abs_len; j++) {
+                    if (bin == -1)
+                        break;
+
+                }
+            }
+#endif
+            // Also x, U, u, octal
+            default:
+                /* Pass through. */
+                wmem_strbuf_append_c(buf, '\\');
+                wmem_strbuf_append_c(buf, c);
+            }
+        } else {
+            /* Pass through. */
+            wmem_strbuf_append_c(buf, c);
+        }
+    }
+
+    return buf;
+}
